impl ToonProjection<9> for crate::types::SymbolsResult {
    const TYPE_NAME: &'static str = "symbols";
    const FIELDS: [&'static str; 9] =
        ["file", "name", "kind", "line", "signature", "owner", "traitImpl", "visibility", "kindDetail"];

